window.AssemblyCall=(()=>{
 let frame=null,watch=null,busy=false,context=null,sdk=null;
 const panel=document.createElement('section');panel.className='call-panel';panel.hidden=true;panel.setAttribute('popover','manual');panel.setAttribute('aria-label','Classroom video call');
 panel.innerHTML='<header><strong id="callTitle">Classroom call</strong><button type="button" data-call="minimize" aria-expanded="true">Minimize</button><button type="button" data-call="leave">Leave call</button></header><p role="status"></p><div id="callFrame"></div>';document.body.append(panel);
 const status=t=>panel.querySelector('[role="status"]').textContent=t;
 function load(){return sdk??=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://unpkg.com/@daily-co/daily-js@0.94.0/dist/daily.js';script.crossOrigin='anonymous';script.onload=resolve;script.onerror=()=>{sdk=null;script.remove();reject(Error('Video controls could not load. Check your connection.'));};document.head.append(script);});}
 async function leave(note=''){clearInterval(watch);watch=null;const old=frame;frame=null;context=null;if(old)await old.destroy();panel.hidden=!note;if(!note&&panel.matches(':popover-open'))panel.hidePopover();status(note);}
 async function join(classId,roomId=null){if(busy)return;busy=true;try{await leave();AssemblyMedia.stop();panel.hidden=false;panel.showPopover();panel.classList.remove('minimized');status('Connecting securely…');const client=AssemblyAccount.connection();const {data,error}=await client.functions.invoke('classroom-call',{body:{class_id:classId,room_id:roomId}});if(error){let message='Call connection unavailable. Confirm classroom-call is deployed in Supabase.';try{message=(await error.context.json()).error||message;}catch{}throw Error(message);}if(data.error)throw Error(data.error);await load();context={classId,stage:data.stage};panel.querySelector('#callTitle').textContent=data.label||'Classroom call';frame=window.Daily.createFrame(panel.querySelector('#callFrame'),{iframeStyle:{width:'100%',height:'100%',border:'0'},showLeaveButton:true});frame.on('left-meeting',()=>leave());frame.on('error',()=>status('Call interrupted. Leave and rejoin to try again.'));await frame.join({url:data.url,token:data.token});status('Camera and microphone start off. Use the call controls to enable them or share your screen.');watch=setInterval(async()=>{if(!context)return;const current=context;try{const {data:s,error:e}=await client.rpc('assembly_session_snapshot',{target_class:classId});if(context!==current)return;if(e||s.stage!==current.stage)await leave(e?'Classroom access could not be verified. Rejoin to try again.':'The teaching stage changed. Join the call from the current lobby or classroom.');}catch{await leave('Connection lost. Rejoin to verify classroom access.');}},5000);}catch(e){await leave(e.message);}finally{busy=false;}}
 panel.addEventListener('click',e=>{const action=e.target.closest('[data-call]')?.dataset.call;if(action==='leave')leave();if(action==='minimize'){const collapsed=panel.classList.toggle('minimized');e.target.textContent=collapsed?'Expand':'Minimize';e.target.setAttribute('aria-expanded',String(!collapsed));}});
 window.addEventListener('pagehide',()=>{clearInterval(watch);frame?.destroy();});return {join,leave};
})();
